227	export async function deleteFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
228	  const user = await requireUser();
229	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
230	  if (!row) return { error: "You don't have a free server." };
231	
232	  try {
233	    const host = await freemcHost();
234	    await withServerSsh(host, async (conn) => {
235	      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
236	      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
237	    });
238	  } catch (e) {
239	    console.error("[free-minecraft] delete cleanup failed (row is removed regardless):", e);
240	  }
241	
242	  await db.freeMinecraftServer.delete({ where: { id: row.id } });
243	  revalidatePath("/dashboard/free-minecraft");
244	  return {};
245	}
