7	/**
8	 * The actual free-Minecraft panel content (create form or full dashboard),
9	 * with no hero/heading of its own so it drops into any page. Shared between
10	 * /dashboard/free-minecraft (kept alive for existing deep links from the
11	 * marketing site and the public server directory — never remove that route)
12	 * and the "Free Minecraft" tab on /dashboard/games.
13	 */
14	export async function FreeMinecraftTabContent() {
15	  const [enabled, domain, dashboard] = await Promise.all([
16	    getSettingBool("free_minecraft_enabled", false),
17	    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
18	    getFreeMinecraftDashboard(),
19	  ]);
20	
21	  const settings = dashboard ? await getFreeMinecraftSettings() : null;
22	
23	  if (!enabled) {
24	    return (
25	      <div className="card max-w-md text-sm text-slate-400">
