import { db } from "./db";

export { SUBDOMAIN_RE, RESERVED_SUBDOMAINS, validateSubdomainFormat } from "./game-subdomain-rules";

/**
 * True when `sub` is free to claim across BOTH the free and paid Minecraft
 * subdomain namespaces (`FreeMinecraftServer.subdomain` and `Server.subdomain`
 * live in different tables but resolve under the same `play.nxeon.cloud` zone,
 * so a name taken in either one is unavailable in both). `excludeServerId`/
 * `excludeFreeMcId` let a rename check availability without tripping over the
 * row's own current value.
 *
 * Server-only (imports `./db`) — a client component must import
 * ./game-subdomain-rules directly for the format check instead.
 */
export async function isSubdomainAvailable(
  sub: string,
  opts?: { excludeServerId?: string; excludeFreeMcId?: string },
): Promise<boolean> {
  const [freeHit, paidHit] = await Promise.all([
    db.freeMinecraftServer.findFirst({
      where: { subdomain: sub, ...(opts?.excludeFreeMcId ? { id: { not: opts.excludeFreeMcId } } : {}) },
      select: { id: true },
    }),
    db.server.findFirst({
      where: { subdomain: sub, ...(opts?.excludeServerId ? { id: { not: opts.excludeServerId } } : {}) },
      select: { id: true },
    }),
  ]);
  return !freeHit && !paidHit;
}
