/**
 * Shared name rules for every `<name>.play.nxeon.cloud` Minecraft subdomain —
 * free-tier (`FreeMinecraftServer.subdomain`) and paid-tier (`Server.subdomain`)
 * alike, since both share the same DNS namespace. Extracted from
 * lib/actions-free-minecraft.ts (the free tier had this first) so the two
 * products can never drift on what a "valid" or "reserved" name is.
 *
 * Deliberately zero-dependency (no `./db`) so it's safe to import from a
 * client component (e.g. the order wizard's live format check) without
 * pulling the Prisma client into the browser bundle — lib/game-subdomain.ts
 * re-exports these plus the DB-backed availability check for server-only code.
 */
export const SUBDOMAIN_RE = /^[a-z0-9]([a-z0-9-]{1,18}[a-z0-9])?$/;
export const RESERVED_SUBDOMAINS = new Set(["www", "api", "admin", "mc", "play", "test", "server", "router"]);

/** Format/reserved-word check only — no DB access. Returns an error message, or null if valid. */
export function validateSubdomainFormat(sub: string): string | null {
  if (!SUBDOMAIN_RE.test(sub) || RESERVED_SUBDOMAINS.has(sub)) {
    return "Pick a name: 3-20 lowercase letters, numbers, or hyphens, not a reserved word.";
  }
  return null;
}

