 *
 * Per-step durations are modeled on a real captured boot log for a
 * plugin-heavy (SkyBlock) create — confirmed live 2026-09-02, itzg/
 * minecraft-server container start to "Done": ~8s init/resolve, ~10s
 * downloading the server jar + plugin jars, ~10s copying configs/writing
 * server.properties + default config downloads, ~10s downloading the
 * Minecraft jar itself + applying patches + starting Bukkit, ~10s JVM boot +
 * plugin init + the session-server environment check, then the single
 * biggest chunk — ~23s preparing the base world's spawn area alone, plus
 * another ~19s for the plugin's own world (e.g. IridiumSkyblock's island) —
 * then plugin enable + RCON/final setup. Simpler presets finish well before
 * reaching the later steps, which is fine — the sequence just stops
 * advancing the moment the action resolves.
 */
const STEPS: { label: string; durationMs: number }[] = [
  { label: "Reserving your world…", durationMs: 5_000 },
