];

export function FreeMinecraftLoader() {
  const [mounted, setMounted] = useState(false);
  const [stepIndex, setStepIndex] = useState(0);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (stepIndex >= STEPS.length - 1) return;
    const id = setTimeout(() => setStepIndex((i) => Math.min(i + 1, STEPS.length - 1)), STEPS[stepIndex].durationMs);
    return () => clearTimeout(id);
  }, [stepIndex]);

  if (!mounted) return null;

  return createPortal(
    <div
      className="fixed inset-0 z-[100] flex flex-col items-center justify-center gap-8 bg-[#05060d]/92 p-6 backdrop-blur-md"

