export type DnsTargetInput = {
  status: string;
  dedicatedIp: { address: string } | null;
  portForwards: { guestPort: number; publicPort: number; protocol: string }[];
  nodePublicIp: string | null | undefined;
  publicIpEnv: string | undefined;
  gamePort: number;
  gameProtocol: "tcp" | "udp";
};

/**
 * Pure resolution of "what ip:port should this server's subdomain point at
 * right now" — no I/O, fully unit-testable. Extracted out of syncGameServerDns
 * so the branching (dedicated vs. NAT-with-forward vs. NAT-without-forward vs.
 * suspended/deleting) can be tested directly.
 *
 * Matches on BOTH guestPort and protocol, not guestPort alone. Several
 * families (cs2/tf2/l4d2/gmod/sdtd — see GAME_JOIN_PORT_OVERRIDE in
 * lib/games.ts) bind the identical port NUMBER for two different services —
 * RCON on tcp, the actual game on udp — so a server can legitimately hold two
 * PortForward rows with the same guestPort and different protocol. Matching
 * on guestPort alone would non-deterministically resolve to whichever forward
 * happens to come first, sometimes handing out the RCON port as the "connect"
 * address — the exact class of bug already found and fixed for the dashboard's
 * raw-IP display 2026-09-06/07 (see joinPortFor's own doc comment). The
 * caller MUST pass the join port+protocol (via `joinPortFor`), not the raw
 * GAME_PORT/health-check port, for the same reason.
 */
export function resolveGameServerDnsTarget(input: DnsTargetInput): { ip: string; port: number } | null {
  if (input.status === "SUSPENDED" || input.status === "DELETING") return null;
  if (input.dedicatedIp) return { ip: input.dedicatedIp.address, port: input.gamePort };
  const forward = input.portForwards.find((f) => f.guestPort === input.gamePort && f.protocol === input.gameProtocol);
  const ip = input.nodePublicIp ?? input.publicIpEnv;
  return forward && ip ? { ip, port: forward.publicPort } : null;
}

